import numpy as np
from itertools import product

n=19
fixed_seq = {4:-1,12:1,13:-1}
fixed_c = {1:-1,2:0,7:-3}
free = [i for i in range(n) if i not in fixed_seq]

def c_k(s, k):
    return sum(s[i]*s[i+k] for i in range(n-k))

count = 0
for vals in product([-1,1], repeat=len(free)):
    s = np.zeros(n, dtype=int)
    for p,v in fixed_seq.items():
        s[p] = v
    for p,v in zip(free, vals):
        s[p] = v
    if all(c_k(s,k)==v for k,v in fixed_c.items()):
        count += 1
        merit = sum(c_k(s,k)**2 for k in range(1,n))
        if merit <= 46:
            print("Found good one:", s.tolist(), "merit=", merit)
            break
print("Total with fixed C:", count)
